Definition sobj (SP shi O n : Z) : Prop := aceil <= SP /\ SP <= O /\ 0 <= n /\ O + n + 64 <= shi /\ shi <= AAPP_HI.

Definition capp (SP shi O n : Z) : Prop := aapp O n \/ sobj SP shi O n.

Lemma sobj_intro : forall m lo shi SP O n, stack0 m lo shi -> aceil <= SP -> SP <= O -> 0 <= n -> O + n + 64 <= shi -> sobj SP shi O n.
Proof. intros m lo shi SP O n SK H1 H2 H3 H4. pose proof (stack0_bounds _ _ _ SK) as [B1 B2]. unfold sobj. lia. Qed.

Lemma sobj_facts : forall SP shi O n, sobj SP shi O n ->
  aceil <= O /\ AHI_LO + 8 <= O /\ O + n + 64 <= AAPP_HI /\ 0 < O /\ 0 <= n /\ AIMG_TOP <= O /\ ALOWSH_LO <= O.
Proof. intros SP shi O n (S1 & S2 & S3 & S4 & S5). pose proof aceil_facts as (AF & _). unfold AHI_LO, AAPP_HI, AIMG_TOP, ALOWSH_LO in *. lia. Qed.

Lemma sobj_sub : forall SP shi O n O' n', sobj SP shi O n -> O <= O' -> O' + n' <= O + n -> 0 <= n' -> sobj SP shi O' n'.
Proof. intros SP shi O n O' n' S H1 H2 H3. unfold sobj in *. lia. Qed.
Lemma sobj_SP_mono : forall SP SP' shi O n, sobj SP shi O n -> aceil <= SP' -> SP' <= SP -> sobj SP' shi O n.
Proof. intros SP SP' shi O n S H1 H2. unfold sobj in *. lia. Qed.

Lemma capp_of_aapp : forall SP shi O n, aapp O n -> capp SP shi O n.
Proof. intros; left; assumption. Qed.
Lemma capp_of_sobj : forall SP shi O n, sobj SP shi O n -> capp SP shi O n.
Proof. intros; right; assumption. Qed.
Lemma capp_sub : forall SP shi O n O' n', capp SP shi O n -> O <= O' -> O' + n' <= O + n -> 0 <= n' -> capp SP shi O' n'.
Proof. intros SP shi O n O' n' [A|S] H1 H2 H3; [left; eapply aapp_sub; eauto| right; eapply sobj_sub; eauto]. Qed.
Lemma capp_SP_mono : forall SP SP' shi O n, capp SP shi O n -> aceil <= SP' -> SP' <= SP -> capp SP' shi O n.
Proof. intros SP SP' shi O n [A|S] H1 H2; [left; exact A| right; eapply sobj_SP_mono; eauto]. Qed.

(* [comment removed for export] *)
Lemma capp_bounds : forall SP shi O n, capp SP shi O n -> 0 <= n ->
  AIMG_TOP <= O /\ (O + n <= aceil \/ (aceil <= SP /\ SP <= O)) /\ O + n < AAPP_HI /\ 0 < O /\ aceil <= hceil.
Proof.
  intros SP shi O n [A|S] Hn.
  - pose proof (aapp_bounds _ _ A Hn). tauto.
  - pose proof (sobj_facts _ _ _ _ S). pose proof aceil_facts. unfold sobj in S. repeat split; try lia.
Qed.
Lemma capp_not_shadowland : forall SP shi O n, capp SP shi O n -> O + n <= ALOWSH_LO \/ AHI_LO <= O.
Proof. intros SP shi O n [A|S]; [exact (aapp_not_shadowland _ _ A)| right; pose proof (sobj_facts _ _ _ _ S); lia]. Qed.
Lemma capp_in_app_mem : forall SP shi O n lo hi, capp SP shi O n -> O <= lo -> hi <= O + n -> in_app_mem lo hi.
Proof.
  intros SP shi O n lo hi [A|S] H1 H2; [eapply aapp_in_app_mem; eauto|].
  pose proof (sobj_facts _ _ _ _ S). right. lia.
Qed.
Lemma aconst_ok_capp : forall SP shi O n l h, capp SP shi O n -> O <= l -> h <= O + n -> aconst_ok (l, h).
Proof.
  intros SP shi O n l h [A|S] H1 H2; [eapply aconst_ok_aapp; eauto|].
  pose proof (sobj_facts _ _ _ _ S). apply aconst_ok_hi. lia.
Qed.
Lemma stack0_ok_capp : forall SP shi O n l h, capp SP shi O n -> O <= l -> h <= O + n -> stack0_ok (l, h).
Proof.
  intros SP shi O n l h [A|S] H1 H2; [eapply stack0_ok_aapp; eauto|].
  pose proof (sobj_facts _ _ _ _ S). apply stack0_ok_app. lia.
Qed.
Lemma noshadow_capp : forall SP shi O n l h, capp SP shi O n -> O <= l -> h <= O + n -> noshadow (l, h).
Proof.
  intros SP shi O n l h C H1 H2. unfold noshadow. cbn [fst snd]. pose proof (capp_not_shadowland _ _ _ _ C). lia.
Qed.
(* [comment removed for export] *)
Lemma capp_disjoint_sh : forall SP shi B k a j, capp SP shi B k -> 0 <= a -> a + j <= AAPP_HI -> 0 <= j ->
  sh a + nsh j <= B \/ B + k <= sh a.
Proof.
  intros SP shi B k a j [A|S] Ha Hj Hj0; [eapply aapp_disjoint_sh; eauto|].
  pose proof (sobj_facts _ _ _ _ S). pose proof (sh_nsh_high a j Ha Hj0 Hj). left. lia.
Qed.

