  Lemma nodup_new_old : forall (NEW LB : list block) b b',
    List.NoDup (map blk_id (NEW ++ LB)) -> In b NEW -> In b' LB -> blk_id b <> blk_id b'.
  Proof.
    intros NEW LB b b' ND Hb Hb' E. rewrite map_app in ND.
    revert ND Hb. induction NEW as [|x NEW IH]; intros ND Hb; [exact Hb|].
    cbn in ND. inversion ND as [|y l NI ND']; subst.
    destruct Hb as [<-|Hb]; [| exact (IH ND' Hb)].
    apply NI. apply in_or_app. right. rewrite E. apply in_map. exact Hb'.
  Qed.
  (* [comment removed for export] *)
  Lemma new_block_outside_cobj : forall s LB m LF m1 s' NEW m' p A n SP shi a k,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> as_RHEAP H s' (NEW ++ LB) m' -> In (p, A, n) NEW -> cobj LB LF SP shi a k -> 0 < k ->
    a + k <= A \/ A + n <= a.
  Proof.
    intros s LB m LF m1 s' NEW m' p A n SP shi a k RH RF RH' Hb C Hk.
    assert (INb : In (p, A, n) (NEW ++ LB)) by (apply in_or_app; left; exact Hb).
    destruct C as [AO|S].
    - eapply (new_block_disjoint_client H HH) with (SP := aceil) (LB := LB); [exact RH'| exact INb| intros b Hb'; apply in_or_app; right; exact Hb'| | eapply (aobj_client H HH); [exact RH| exact RF| exact AO]| lia| exact Hk].
      intros b0 Hb' E. exact (nodup_new_old NEW LB (p, A, n) b0 (ah_nodup H HH _ _ _ RH') Hb Hb' (eq_sym E)).
    - pose proof (ah_blocks H HH _ _ _ (p, A, n) RH' INb) as (_ & _ & _ & _ & R5 & _). cbn in R5. unfold sobj in S. right. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma cobj_apres_accessible : forall s LB m0 LF m1 SP SP' shi m m' A n a k,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> cobj LB LF SP shi A n -> apres H LB SP' m m' ->
    accessible m a k -> A <= a -> a + k <= A + n -> accessible m' a k.
  Proof.
    intros s LB m0 LF m1 SP SP' shi m m' A n a k RH RF C AP AC H1 H2. eapply apres_accessible; [exact AP| exact AC|].
    intros x Hx. eapply cobj_shclient; [exact RH| exact RF| exact C| lia].
  Qed.

