  Lemma xclient_range_cobj : forall s LB m0 LF m1 SP SP' shi X XS O n,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> cobj LB LF SP shi O n -> 0 <= n -> SP' <= SP ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X -> Forall (fs_scratch H LF) XS ->
    xclient_range H LB SP' (X ++ XS) O n.
  Proof.
    intros s LB m0 LF m1 SP SP' shi X XS O n RH RF C Hn LE FX FS. destruct C as [AO|S]; [eapply (xclient_range_aobj H HH); eauto|].
    split; [unfold sobj in S; left; lia|]. apply Forall_app. split; [exact FX|].
    eapply Forall_impl; [| exact FS]. intros iv K. pose proof (scratch_facts H HH LF m1 [] iv RF K) as (_ & _ & K2). unfold sobj in S. right. lia.
  Qed.

