  Lemma cobj_xpres_accessible : forall s LB m0 LF m1 SP SP' shi X XS m m' O n a k,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> cobj LB LF SP shi O n -> 0 <= n ->
    xpres H LB SP' (X ++ XS) m m' -> Forall noshadow X -> Forall (fs_scratch H LF) XS ->
    accessible m a k -> O <= a -> a + k <= O + n -> accessible m' a k.
  Proof.
    intros s LB m0 LF m1 SP SP' shi X XS m m' O n a k RH RF C Hn XP FX FS AC H1 H2.
    eapply (xpres_accessible H); [exact XP| exact AC|]. intros x Hx. eapply xclient_sh_cobj; eauto. lia.
  Qed.

