  Lemma fsobj_scratch_c : forall LF SP shi O n m iv,
    as_RFS H LF m -> fsobj H LF O n -> 0 <= O -> 0 <= n -> O + n <= AAPP_HI -> capp SP shi O n -> fs_scratch H LF iv ->
    O + n <= fst iv \/ snd iv <= O.
  Proof.
    intros LF SP shi O n m iv R OB HO Hn Htop [A|S] FS; [eapply (fsobj_scratch H HH); eauto|].
    pose proof (scratch_facts H HH LF m [] iv R FS) as (_ & K1 & K2). pose proof (sobj_facts _ _ _ _ S). right. lia.
  Qed.
  Lemma Forall_scratch_c : forall LF m XS SP shi O n, as_RFS H LF m -> fsobj H LF O n -> 0 <= n -> O + n <= AAPP_HI -> capp SP shi O n ->
    Forall (fs_scratch H LF) XS -> Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) XS.
  Proof.
    intros LF m XS SP shi O n RF OB Hn Htop C FX. pose proof (capp_bounds _ _ _ _ C Hn) as (B1 & _).
    eapply Forall_impl; [| exact FX]. intros iv FS. eapply fsobj_scratch_c; eauto. unfold AIMG_TOP in B1. lia.
  Qed.
  Lemma disjoint_scratch_c : forall LF m XS SP shi O n, as_RFS H LF m -> fsobj H LF O n -> 0 <= n -> O + n <= AAPP_HI -> capp SP shi O n ->
